import { z } from "zod";
import { SHAPE_FILLS, SHAPE_KINDS } from "./shape";
import { MAX_STICKY_BYTES } from "./sticky";
import { DEFAULT_STROKE_STYLE, STROKE_STYLES } from "./style";
import { MAX_WIDTH, MIN_WIDTH } from "./width";

export const objectId = z.string().regex(/^[0-9A-Za-z_-]{1,64}$/);

export const nativeZoom = z.int().min(-40).max(40);

export const bbox = z.strictObject({
  minX: z.number(),
  minY: z.number(),
  maxX: z.number(),
  maxY: z.number(),
});

export const colour = z.int().min(0).max(5);

export const rgb = z.int().min(0).max(0xffffff);

export const width = z.number().min(MIN_WIDTH).max(MAX_WIDTH);

export const strokeStyle = z.enum(STROKE_STYLES).default(DEFAULT_STROKE_STYLE);

export const pencilSize = z.enum(["Small", "Medium", "Large"]);

export const point = z.tuple([z.number(), z.number(), z.number().min(0).max(1)]);

export const shapePoint = z.tuple([z.number(), z.number()]);

export const stroke = z.strictObject({
  type: z.literal("Stroke"),
  objectId,
  nativeZoom,
  bbox,
  colour,
  rgb: rgb.optional(),
  size: pencilSize,
  width: width.optional(),
  style: strokeStyle,
  points: z.array(point).min(1).max(4096),
});

export const shape = z.strictObject({
  type: z.literal("Shape"),
  objectId,
  nativeZoom,
  bbox,
  colour,
  rgb: rgb.optional(),
  size: pencilSize,
  width: width.optional(),
  style: strokeStyle,
  kind: z.enum(SHAPE_KINDS),
  start: shapePoint,
  end: shapePoint,
  fill: z.enum(SHAPE_FILLS),
});

export const text = z.strictObject({
  type: z.literal("Text"),
  objectId,
  nativeZoom,
  bbox,
  colour,
  rgb: rgb.optional(),
  size: pencilSize,
  width: width.optional(),
  text: z.string().min(1).max(4096),
});

export const sticky = z.strictObject({
  type: z.literal("Sticky"),
  objectId,
  nativeZoom,
  bbox,
  rgb,
  background: rgb,
  width,
  text: z.string().max(MAX_STICKY_BYTES),
});

export const stallionObject = z.discriminatedUnion("type", [stroke, shape, text, sticky]);

export type Bbox = z.infer<typeof bbox>;
export type Point = z.infer<typeof point>;
export type ShapePoint = z.infer<typeof shapePoint>;
export type PencilSize = z.infer<typeof pencilSize>;
export type Stroke = z.infer<typeof stroke>;
export type Shape = z.infer<typeof shape>;
export type Text = z.infer<typeof text>;
export type Sticky = z.infer<typeof sticky>;
export type StallionObject = z.infer<typeof stallionObject>;
export const MAX_STICKY_BYTES = 4096;

const utf8 = new TextEncoder();

export const utf8Length = (text: string): number => utf8.encode(text).length;

export const clampUtf8 = (text: string, max = MAX_STICKY_BYTES): string => {
  if (utf8Length(text) <= max) return text;
  let kept = "";
  let bytes = 0;
  for (const char of text) {
    const size = utf8Length(char);
    if (bytes + size > max) break;
    kept += char;
    bytes += size;
  }
  return kept;
};
export { type DecodeResult, decode, encode } from "./codec";
export * from "./colour";
export * from "./frame";
export * from "./ink";
export * from "./model";
export * from "./shape";
export * from "./sticky";
export * from "./style";
export * from "./width";
import { Encoder } from "cbor-x";
import { validate } from "../generated/validate.js";
import { withRgb } from "./colour";
import type { StallionObject } from "./model";
import { withStyle } from "./style";
import { withWidth } from "./width";

export type DecodeResult = { ok: true; value: StallionObject } | { ok: false; error: string };

const cbor = new Encoder({ useRecords: false, mapsAsObjects: true, variableMapSize: true });

const normalise = (object: StallionObject): StallionObject => {
  if (object.type === "Sticky") return object;
  const complete = withWidth(withRgb(object));
  return complete.type === "Text" ? complete : withStyle(complete);
};

const describeErrors = (): string =>
  (validate.errors ?? []).map((e) => `${e.instancePath || "/"} ${e.message ?? ""}`).join("; ");

export const encode = (object: StallionObject): Uint8Array => {
  if (!validate(object)) {
    throw new TypeError(`Cannot encode an invalid object: ${describeErrors()}`);
  }
  return cbor.encode(normalise(object));
};

export const decode = (bytes: Uint8Array): DecodeResult => {
  const value: unknown = cbor.decode(bytes);
  if (!validate(value)) {
    return { ok: false, error: describeErrors() };
  }
  return { ok: true, value: normalise(value) };
};
