    reportPresence();
    requestRender();
  };

  const publishViewport = () => {
    if (!awareness) return;
    const { width, height } = size();
    const viewport = viewportOf(camera, width, height);
    if (
      published &&
      published.x === viewport.x &&
      published.y === viewport.y &&
      published.zoom === viewport.zoom
