202	const remoteCursor = (clientId: number, state: unknown): RemoteCursor | undefined => {
203	  if (typeof state !== "object" || state === null) return undefined;
204	  const { cursor, user } = state as Record<string, unknown>;
205	  if (typeof cursor !== "object" || cursor === null) return undefined;
206	  const { x, y } = cursor as Record<string, unknown>;
207	  if (typeof x !== "number" || typeof y !== "number") return undefined;
208	  const name = displayName(
209	    typeof user === "object" && user !== null ? (user as { name?: unknown }).name : undefined,
210	  );
211	  return { x, y, name, colour: presenceColour(clientId) };
