216	const DEFAULT_CAMERA: Camera = { x: 0, y: 0, zoom: 1 };
217	
218	const isCamera = (value: unknown): value is Camera => {
219	  if (typeof value !== "object" || value === null) return false;
220	  const { x, y, zoom } = value as Record<string, unknown>;
221	  return (
222	    typeof x === "number" &&
223	    typeof y === "number" &&
224	    typeof zoom === "number" &&
225	    Number.isFinite(x) &&
226	    Number.isFinite(y) &&
227	    zoom > 0 &&
228	    Number.isFinite(zoom)
229	  );
230	};
