322	  let cursorSentAt = 0;
323	  let animation = 0;
324	  let reported: SurfaceView | undefined;
325	  let dragButton = 0;
326	  let presence = NO_PRESENCE;
327	  let published: Viewport | undefined;
328	  let publishedAt = Number.NEGATIVE_INFINITY;
