341	    const dpr = window.devicePixelRatio || 1;
342	    const { width, height } = size();
343	    ctx.setTransform(1, 0, 0, 1, 0, 0);
344	    ctx.fillStyle = PAPER;
345	    ctx.fillRect(0, 0, canvas.width, canvas.height);
