347	    const toDevice = (world: Point): Point => ({
348	      x: (world.x - camera.x) * camera.zoom * dpr,
349	      y: (world.y - camera.y) * camera.zoom * dpr,
350	    });
351	    const markers: Marker[] = [];
352	    for (const original of ordered) {
353	      const resized =
354	        resizing?.objectId === original.object.objectId ? resizing.preview : undefined;
355	      const entry = resized ?? original;
356	      const dragged = drag?.objectId === entry.object.objectId ? drag : undefined;
357	      const culled = dragged || resized ? "Draw" : cull(entry.object.bbox, view, camera.zoom);
358	      if (culled === "Skip") continue;
359	      const colour = rgbHex(colourOf(entry.object));
360	      if (culled === "Marker") {
361	        markers.push({ ...toDevice(bboxCentre(entry.object.bbox)), style: colour });
362	        continue;
363	      }
364	      const offset = dragged ?? { dx: 0, dy: 0 };
365	      if (entry.type === "Sticky") {
366	        const { bbox } = entry.object;
367	        const topLeft = worldToScreen(camera, {
368	          x: bbox.minX + offset.dx,
369	          y: bbox.minY + offset.dy,
370	        });
371	        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
372	        paintSticky(
373	          ctx,
374	          entry.object,
375	          entry.lines,
376	          {
