378	            width: (bbox.maxX - bbox.minX) * camera.zoom,
379	            height: (bbox.maxY - bbox.minY) * camera.zoom,
380	          },
381	          camera.zoom,
382	          editing?.objectId !== entry.object.objectId,
383	        );
384	        continue;
385	      }
386	      if (entry.type === "Shape") {
