739	    const { anchor, corner, from } = resizing;
740	    const world = screenToWorld(camera, screen);
741	    const factor = (moved: number, span: number): number => (span === 0 ? 1 : moved / span);
742	    const by: Scale = {
743	      anchor,
744	      sx: factor(corner.x + world.x - from.x - anchor.x, corner.x - anchor.x),
745	      sy: factor(corner.y + world.y - from.y - anchor.y, corner.y - anchor.y),
746	    };
747	    const result = by.sx === 1 && by.sy === 1 ? undefined : scale(entry, by, measureAt);
748	    resizing = { ...resizing, result, preview: result && entryOf(result) };
749	  };
750	
751	  const finishResize = () => {
752	    const result = resizing?.result;
753	    resizing = undefined;
754	    if (result) source.commit(result);
755	  };
756	
757	  const discard = (objectId: string) => {
758	    if (selected === objectId && !source.objects.has(objectId)) selected = undefined;
759	    if (editing?.objectId === objectId && !source.objects.has(objectId)) editing = undefined;
760	    const entry = entries.get(objectId);
761	    if (!entry) return;
762	    entries.delete(objectId);
763	    ordered = ordered.filter((other) => other !== entry);
764	  };
765	
766	  const onObjects = (changed: ReadonlySet<string>) => {
767	    for (const objectId of changed) {
768	      const stored = source.objects.get(objectId);
769	      if (stored) add(stored);
770	      else discard(objectId);
771	    }
772	    if (inks.some((ink) => changed.has(ink.strokeId))) {
773	      for (const ink of inks) if (changed.has(ink.strokeId)) landed.add(ink.strokeId);
774	      inks = inks.filter((ink) => !landed.has(ink.strokeId));
775	    }
776	    requestRender();
777	    reportView();
778	  };
779	
780	  const reportPresence = () => {
781	    if (!awareness) return;
782	    const next: Presence = {
783	      peers: peersOf(awareness.getStates(), awareness.clientID).map(
784	        ({ viewport: _viewport, ...peer }) => peer,
785	      ),
786	      following: follow.target,
787	    };
788	    if (samePresence(presence, next)) return;
789	    presence = next;
790	    onPresence(presence);
791	  };
792	
793	  const onAwareness = () => {
794	    if (!awareness) return;
795	    const states = awareness.getStates();
796	    cursors = [...states].flatMap(([clientId, state]) => {
797	      if (clientId === awareness.clientID) return [];
798	      const cursor = remoteCursor(clientId, state);
799	      return cursor ? [cursor] : [];
800	    });
801	    const live = [...reader.read(awareness.getStates(), awareness.clientID).values()];
802	    for (const strokeId of landed) {
803	      if (!live.some((ink) => ink.strokeId === strokeId)) landed.delete(strokeId);
804	    }
805	    for (const ink of live) if (entries.has(ink.strokeId)) landed.add(ink.strokeId);
806	    inks = live.filter((ink) => !landed.has(ink.strokeId));
807	    follow.peers(peersOf(states, awareness.clientID));
808	    reportPresence();
809	    requestRender();
810	  };
811	
812	  const publishViewport = () => {
813	    if (!awareness) return;
814	    const { width, height } = size();
815	    const viewport = viewportOf(camera, width, height);
816	    if (
817	      published &&
818	      published.x === viewport.x &&
819	      published.y === viewport.y &&
820	      published.zoom === viewport.zoom
821	    )
822	      return;
823	    const wait = publishedAt + PRESENCE_THROTTLE_MS - performance.now();
824	    if (wait > 0) {
825	      if (publishTimer === undefined) {
826	        publishTimer = setTimeout(() => {
827	          publishTimer = undefined;
828	          publishViewport();
829	        }, wait);
830	      }
831	      return;
832	    }
833	    published = viewport;
834	    publishedAt = performance.now();
835	    awareness.setLocalStateField("presence", {
836	      colour: presenceColour(awareness.clientID),
837	      viewport,
838	    });
839	  };
840	
841	  const shareCursor = (screen: Point | undefined) => {
842	    if (!awareness) return;
843	    if (!screen) {
844	      awareness.setLocalStateField("cursor", null);
845	      return;
846	    }
847	    const now = performance.now();
848	    if (now - cursorSentAt < CURSOR_THROTTLE_MS) return;
849	    cursorSentAt = now;
850	    awareness.setLocalStateField("cursor", screenToWorld(camera, screen));
851	  };
852	
853	  const reportView = () => {
854	    const contentLevels = [...new Set(ordered.map((entry) => entry.object.nativeZoom))].sort(
855	      (a, b) => a - b,
856	    );
857	    const level = levelOf(camera.zoom);
858	    if (
859	      reported &&
860	      reported.level === level &&
861	      reported.contentLevels.join() === contentLevels.join()
862	    )
863	      return;
864	    reported = { level, contentLevels };
865	    onView(reported);
866	  };
867	
868	  const updateView = () => {
869	    const { width, height } = size();
870	    source.view(viewBounds(camera, width, height), camera.zoom);
871	  };
872	
873	  const settle = () => {
874	    clearTimeout(settleTimer);
875	    settleTimer = setTimeout(() => saveCamera(boardId, camera), 150);
876	    updateView();
877	  };
878	
879	  const moveCamera = (next: Camera) => {
880	    if (!isCamera(next)) return;
881	    camera = next;
882	    requestRender();
883	    settle();
884	    reportView();
885	    publishViewport();
886	  };
887	
888	  const shareDraft = (next: Draft) => {
889	    const { objectId, rgb, width, style, nativeZoom, points } = next;
890	    publisher?.start({
891	      strokeId: objectId,
892	      colour: nearestColour(rgb),
893	      rgb,
894	      size: nearestSize(width),
895	      width,
896	      style,
897	      nativeZoom,
898	    });
899	    publisher?.extend(points);
900	  };
901	  const follow = createFollow({
902	    camera: () => camera,
903	    size,
904	    move: moveCamera,
905	    requestFrame: (step) => requestAnimationFrame(step),
906	    cancelFrame: (handle) => cancelAnimationFrame(handle),
907	    now: () => performance.now(),
908	    onChange: reportPresence,
909	  });
910	
911	  const commit = () => {
912	    if (!draft) return;
913	    publisher?.finish();
914	    const stored = finishDraft(draft);
915	    draft = undefined;
916	    if (stored) {
917	      source.commit(stored);
918	      onCommit();
919	    }
920	    publisher?.clear();
921	  };
922	
923	  const commitShape = () => {
924	    if (!shapeDraft) return;
925	    const stored = finishShape(shapeDraft);
926	    shapeDraft = undefined;
927	    if (!stored) return;
928	    source.commit(stored);
929	    onCommit();
930	  };
931	
932	  const toLocal = (clientX: number, clientY: number): Point => {
933	    const rect = canvas.getBoundingClientRect();
934	    return { x: clientX - rect.left, y: clientY - rect.top };
935	  };
936	
937	  const localPoint = (event: PointerEvent | WheelEvent): Point =>
938	    toLocal(event.clientX, event.clientY);
939	
940	  const pressureOf = (event: PointerEvent): number =>
941	    event.pointerType === "pen" ? Math.min(1, Math.max(0, event.pressure)) : 0.5;
942	
943	  const addPoint = (screen: Point, pressure: number) => {
944	    if (!draft) return;
945	    const world = screenToWorld(camera, screen);
946	    if (draft.points.length >= MAX_POINTS) {
947	      const next = continueDraft(draft);
948	      commit();
949	      draft = next;
950	      shareDraft(next);
951	    }
952	    const point: [number, number, number] = [world.x, world.y, pressure];
953	    draft.points.push(point);
954	    publisher?.extend([point]);
955	  };
956	
957	  const pointerKind = (event: PointerEvent): PointerKind =>
958	    event.pointerType === "pen" || event.pointerType === "touch" ? event.pointerType : "mouse";
959	
960	  const apply = (effects: readonly Effect[], event?: PointerEvent) => {
961	    for (const effect of effects) {
962	      switch (effect.type) {
963	        case "StartStroke": {
964	          finishEdit();
965	          const tool = currentTool();
966	          if (tool.mode === "Sticky") {
967	            stickyPress = { point: effect.point, secondary: effect.secondary };
968	            break;
969	          }
970	          if (tool.mode === "Select") {
971	            startDrag(effect.point);
972	            break;
973	          }
974	          if (tool.mode === "Eraser") {
975	            eraser = undefined;
976	            eraseTo(effect.point);
977	            break;
978	          }
979	          if (tool.mode === "Shape") {
980	            shapeDraft = startShape(
981	              tool.shape,
982	              tool.fill,
983	              effect.secondary ? tool.secondary : tool.primary,
984	              tool.width,
985	              tool.style,
986	              camera.zoom,
987	              screenToWorld(camera, effect.point),
988	            );
989	            break;
990	          }
991	          draft = startDraft(
992	            effect.secondary ? tool.secondary : tool.primary,
993	            tool.width,
994	            tool.style,
995	            camera.zoom,
996	          );
997	          shareDraft(draft);
998	          addPoint(effect.point, event ? pressureOf(event) : 0.5);
999	          break;
1000	        }
1001	        case "StartResize":
1002	          startResize(effect.point);
1003	          break;
1004	        case "ExtendStroke": {
1005	          if (!event) break;
1006	          if (resizing) {
1007	            resizeTo(localPoint(event));
1008	            break;
1009	          }
1010	          const samples = event.getCoalescedEvents?.() ?? [];
1011	          for (const sample of samples.length > 0 ? samples : [event]) {
1012	            if (drag) dragTo(localPoint(sample));
1013	            else if (eraser) eraseTo(localPoint(sample));
1014	            else if (shapeDraft) shapeDraft.end = screenToWorld(camera, localPoint(sample));
1015	            else addPoint(localPoint(sample), pressureOf(sample));
1016	          }
1017	          break;
1018	        }
1019	        case "CommitStroke": {
1020	          eraser = undefined;
1021	          const press = stickyPress;
1022	          stickyPress = undefined;
1023	          if (press) placeSticky(press);
1024	          drop();
1025	          finishResize();
1026	          commit();
1027	          commitShape();
1028	          source.history.checkpoint();
1029	          break;
1030	        }
1031	        case "DiscardStroke":
1032	          eraser = undefined;
1033	          stickyPress = undefined;
1034	          drag = undefined;
1035	          resizing = undefined;
1036	          draft = undefined;
1037	          shapeDraft = undefined;
1038	          publisher?.clear();
1039	          source.history.checkpoint();
1040	          break;
1041	        case "Pan":
1042	          follow.stop();
1043	          moveCamera(pan(camera, effect.dx, effect.dy));
1044	          break;
1045	        case "Pinch":
1046	          follow.stop();
1047	          moveCamera(pinch(camera, effect));
1048	          break;
1049	      }
1050	    }
1051	    if (effects.length > 0) requestRender();
1052	  };
1053	
1054	  const stopAnimation = () => {
1055	    cancelAnimationFrame(animation);
1056	    animation = 0;
1057	  };
1058	
1059	  const zoomToLevel = (level: number) => {
1060	    follow.stop();
1061	    stopAnimation();
1062	    const from = camera;
1063	    const { width, height } = size();
1064	    const centre = { x: width / 2, y: height / 2 };
1065	    const target = zoomForLevel(level);
1066	    const started = performance.now();
1067	    const step = (now: number) => {
1068	      const t = Math.min(1, (now - started) / LEVEL_ANIMATION_MS);
1069	      moveCamera(zoomTo(from, centre, from.zoom * (target / from.zoom) ** easeOut(t)));
1070	      if (t < 1) {
1071	        animation = requestAnimationFrame(step);
1072	        return;
1073	      }
1074	      animation = 0;
1075	      moveCamera(zoomTo(from, centre, target));
1076	    };
1077	    animation = requestAnimationFrame(step);
1078	  };
1079	
1080	  const isPointerEvent = (event: Event): event is PointerEvent => "pointerId" in event;
1081	
1082	  const onDrag = ({ event, intentional }: { event: Event; intentional: boolean }) => {
1083	    if (!isPointerEvent(event)) return;
1084	    const first = event.type === "pointerdown";
1085	    const cancelled = event.type === "pointercancel";
1086	    const last = cancelled || event.type === "pointerup" || event.type === "lostpointercapture";
1087	    if (first) {
1088	      event.preventDefault();
1089	      stopAnimation();
1090	      dragButton = event.button;
1091	    }
1092	    const effects = input.drag(
1093	      {
1094	        first,
1095	        last,
1096	        cancelled,
1097	        intentional,
1098	        kind: pointerKind(event),
1099	        button: dragButton,
1100	        point: localPoint(event),
1101	        time: event.timeStamp,
1102	      },
1103	      {
1104	        panTool: currentTool().mode === "Pan",
1105	        spaceDown,
1106	        onHandle:
1107	          first && currentTool().mode === "Select" && handleAt(localPoint(event)) !== undefined,
1108	      },
1109	    );
1110	    apply(effects, event);
1111	    if (!first || event.pointerType !== "touch") return;
1112	    clearTimeout(pendingTimer);
1113	    pendingTimer = setTimeout(() => apply(input.tick(performance.now())), PENDING_MS);
1114	  };
1115	
1116	  const onPinch = ({
1117	    first,
1118	    last,
1119	    origin,
1120	    da,
1121	  }: {
1122	    first: boolean;
1123	    last: boolean;
1124	    origin: [number, number];
1125	    da: [number, number];
1126	  }) => {
1127	    if (first) {
1128	      stopAnimation();
1129	      follow.stop();
1130	    }
1131	    apply(input.pinch({ first, last, origin: toLocal(origin[0], origin[1]), distance: da[0] }));
1132	  };
1133	
1134	  const onWheel = ({ event }: { event: WheelEvent }) => {
1135	    event.preventDefault();
1136	    stopAnimation();
1137	    follow.stop();
1138	    const factor = wheelFactor(event.ctrlKey ? event.deltaY * 3 : event.deltaY, event.deltaMode);
1139	    moveCamera(zoomAt(camera, localPoint(event), factor));
1140	  };
1141	
1142	  const onPointerMove = (event: PointerEvent) => shareCursor(localPoint(event));
1143	
1144	  const onKey = (event: KeyboardEvent) => {
1145	    if (event.target instanceof HTMLInputElement || event.target instanceof HTMLTextAreaElement)
1146	      return;
1147	    if (event.type === "keydown" && (event.key === "Delete" || event.key === "Backspace")) {
1148	      if (selected === undefined || currentTool().mode !== "Select") return;
1149	      event.preventDefault();
1150	      source.erase(selected);
1151	      source.history.checkpoint();
1152	      selected = undefined;
1153	      requestRender();
1154	      return;
1155	    }
1156	    if (event.code !== "Space") return;
1157	    event.preventDefault();
1158	    spaceDown = event.type === "keydown";
1159	  };
1160	
1161	  const onPointerLeave = () => shareCursor(undefined);
1162	
1163	  const preventDefault = (event: Event) => event.preventDefault();
1164	
1165	  const unobserve = source.objects.observe(onObjects);
1166	  const unobserveHints = source.hints.observe(requestRender);
1167	  awareness?.on("change", onAwareness);
1168	
1169	  const observer = new ResizeObserver(() => {
1170	    resize();
1171	    settle();
1172	  });
1173	  observer.observe(canvas);
1174	
1175	  const gesture = new Gesture(
1176	    canvas,
1177	    { onDrag, onPinch, onWheel },
1178	    {
1179	      eventOptions: { passive: false },
1180	      drag: {
1181	        threshold: DRAG_THRESHOLD_PX,
1182	        triggerAllEvents: true,
1183	        pointer: { buttons: -1, keys: false },
1184	      },
1185	      pinch: { pointer: { touch: true }, pinchOnWheel: false },
1186	    },
1187	  );
1188	  canvas.addEventListener("pointermove", onPointerMove);
1189	  canvas.addEventListener("pointerleave", onPointerLeave);
1190	  canvas.addEventListener("contextmenu", preventDefault);
1191	  for (const type of BLOCKED_TOUCH_EVENTS) {
1192	    canvas.addEventListener(type, preventDefault, { passive: false });
1193	  }
1194	  window.addEventListener("keydown", onKey);
1195	  window.addEventListener("keyup", onKey);
1196	
1197	  resize();
1198	  onObjects(new Set(source.objects.keys()));
1199	  onAwareness();
1200	  updateView();
1201	  reportView();
1202	
1203	  return {
1204	    zoomToLevel,
1205	    follow(clientId) {
1206	      if (clientId === undefined || clientId === follow.target) {
1207	        follow.stop();
1208	        return;
1209	      }
1210	      stopAnimation();
1211	      follow.start(clientId);
1212	    },
1213	    editText(text) {
1214	      if (editing) editing = { ...editing, text };
1215	    },
1216	    finishEdit,
1217	    panBy(dx, dy) {
1218	      follow.stop();
1219	      moveCamera(pan(camera, dx, dy));
1220	    },
1221	    dispose() {
1222	      clearTimeout(settleTimer);
1223	      clearTimeout(publishTimer);
1224	      follow.dispose();
1225	      clearTimeout(pendingTimer);
1226	      publisher?.clear();
1227	      cancelAnimationFrame(frame);
1228	      stopAnimation();
1229	      gesture.destroy();
1230	      observer.disconnect();
1231	      canvas.removeEventListener("pointermove", onPointerMove);
1232	      canvas.removeEventListener("pointerleave", onPointerLeave);
1233	      canvas.removeEventListener("contextmenu", preventDefault);
1234	      for (const type of BLOCKED_TOUCH_EVENTS) canvas.removeEventListener(type, preventDefault);
1235	      window.removeEventListener("keydown", onKey);
1236	      window.removeEventListener("keyup", onKey);
1237	      unobserve();
1238	      unobserveHints();
1239	      awareness?.off("change", onAwareness);
1240	      saveCamera(boardId, camera);
1241	    },
1242	  };
1243	}
