    });
  const [first, ...rest] = points;
  await touch("touchStart", first);
  for (const [index, point] of rest.entries()) {
    await touch("touchMove", point);
    if (index === Math.floor(rest.length / 2)) await midway();
  }
  await touch("touchEnd");
  await cdp.detach();
};

