    if ((counts.tiles ?? 0) === 0) fail(\`\${label}: no tile stored in IndexedDB after reload\`);
    check();
    return {
      lines: kept.lines,
      screenshots: [placing.path, editing.path, committed.path, reloaded.path],
    };
  } finally {
    await context.close();
  }
};
`;
