import { readFileSync, writeFileSync, existsSync, mkdirSync } from "node:fs";
import { join, extname } from "node:path";

const WT = process.env.WT;
const { chromium, devices } = await import(join(WT, "node_modules/playwright/index.mjs"));
const { routeAccessHeaders } = await import(join(WT, "npm-scripts/env.mjs"));
const [mode, base] = process.argv.slice(2);
const OUT = join(process.env.HOME, "development/.tmp/stallion-text", mode);
mkdirSync(OUT, { recursive: true });
const DIST = join(WT, "apps/web/dist");
const TYPES = { ".js": "text/javascript", ".css": "text/css", ".html": "text/html", ".png": "image/png", ".svg": "image/svg+xml", ".webmanifest": "application/manifest+json" };
const RED = [0xe5, 0x48, 0x4d];
const BLUE = [0x00, 0x90, 0xff];
const report = [];

const board = () => {
  const bytes = crypto.getRandomValues(new Uint8Array(16));
  let v = 0n;
  for (const b of bytes) v = (v << 8n) | BigInt(b);
  return v.toString(36).padStart(25, "0");
};

const tapAt = async (page, points) => {
  const cdp = await page.context().newCDPSession(page);
  const touch = (type, p) => cdp.send("Input.dispatchTouchEvent", { type, touchPoints: p ? [{ x: p.x, y: p.y, id: 1, radiusX: 2, radiusY: 2 }] : [] });
  const [first, ...rest] = points;
  await touch("touchStart", first);
  for (const p of rest) await touch("touchMove", p);
  await touch("touchEnd");
  await cdp.detach();
};

const line = (a, b, n = 16) => Array.from({ length: n + 1 }, (_, i) => ({ x: a.x + ((b.x - a.x) * i) / n, y: a.y + ((b.y - a.y) * i) / n }));

const run = async (browser, device) => {
  const tag = device.toLowerCase().replace(/\W+/g, "-");
  const context = await browser.newContext({ ...devices[device], colorScheme: "light", serviceWorkers: mode === "local" ? "block" : "allow" });
  const errors = [];
  if (mode === "local") {
    await context.route("http://localhost:59999/**", (route) => {
      const url = new URL(route.request().url());
      if (url.pathname.startsWith("/api/")) return route.fulfill({ status: 503, body: "" });
      let file = join(DIST, url.pathname);
      if (!existsSync(file) || url.pathname === "/" || url.pathname.startsWith("/b/")) file = join(DIST, "index.html");
      return route.fulfill({ status: 200, body: readFileSync(file), contentType: TYPES[extname(file)] ?? "application/octet-stream" });
    });
  } else {
    await routeAccessHeaders(context, new URL(base).origin);
  }
  const page = await context.newPage();
  page.on("console", (m) => m.type() === "error" && errors.push(m.text()));
  page.on("pageerror", (e) => errors.push(`pageerror ${e.message}`));
  const shot = async (name) => {
    const path = join(OUT, `${tag}-${name}.png`);
    const buffer = await page.screenshot();
    writeFileSync(path, buffer);
    return { path, buffer };
  };
  const pixels = (buffer, rgb, limit = 60) =>
    page.evaluate(async ([b64, fg, lim]) => {
      const bytes = Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
      const bmp = await createImageBitmap(new Blob([bytes], { type: "image/png" }));
      const c = new OffscreenCanvas(bmp.width, bmp.height);
      const ctx = c.getContext("2d");
      ctx.drawImage(bmp, 0, 0);
      const { width, height, data } = ctx.getImageData(0, 0, bmp.width, bmp.height);
      const box = { n: 0, minX: 1e9, minY: 1e9, maxX: -1, maxY: -1 };
      for (let y = 0; y < height; y++)
        for (let x = 0; x < width; x++) {
          const i = (y * width + x) * 4;
          if (Math.abs(data[i] - fg[0]) + Math.abs(data[i + 1] - fg[1]) + Math.abs(data[i + 2] - fg[2]) > lim) continue;
          box.n++;
          box.minX = Math.min(box.minX, x); box.minY = Math.min(box.minY, y);
          box.maxX = Math.max(box.maxX, x); box.maxY = Math.max(box.maxY, y);
        }
      return box;
    }, [buffer.toString("base64"), rgb, limit]);
  const scale = devices[device].deviceScaleFactor ?? 1;
  const palette = async (fn) => {
    const more = page.getByRole("button", { name: "More tools" });
    if (await more.isVisible()) await more.tap();
    await page.locator("[data-toolbar-flip]").tap();
    const p = page.locator('.toolbar[data-layout="Palette"]');
    await p.waitFor({ state: "visible", timeout: 5000 });
    await page.waitForTimeout(300);
    await fn(p);
    await page.locator("[data-toolbar-flip]").tap();
    await p.waitFor({ state: "hidden", timeout: 5000 });
    const fewer = page.getByRole("button", { name: "Fewer tools" });
    if (await fewer.isVisible()) await fewer.tap();
    await page.waitForTimeout(300);
  };
  const undo = async () => {
    const more = page.getByRole("button", { name: "Undo" });
    await more.first().tap();
    await page.waitForTimeout(600);
  };
  const url = mode === "local" ? `http://localhost:59999/b/${board()}` : `${base}/b/${board()}`;
  const out = { device, url, steps: {} };
  try {
    await page.goto(url, { waitUntil: "load" });
    await page.locator("canvas.surface").waitFor({ state: "visible", timeout: 15000 });
    await page.waitForTimeout(800);
    const vp = page.viewportSize();
    const at = { x: Math.round(Math.max(24, vp.width / 2 - 160)), y: Math.round(vp.height * 0.3) };
    await palette(async (p) => {
      await p.getByRole("button", { name: "Colour 2", exact: true }).tap();
      await p.getByRole("button", { name: "Text tool" }).tap();
    });
    await tapAt(page, [at]);
    const editor = page.locator(".sticky-editor:not(.idle) textarea");
    await editor.waitFor({ state: "visible", timeout: 5000 });
    await page.keyboard.type("Hello from the text tool, a line that wraps once it gets narrow");
    await page.waitForTimeout(300);
    const editing = await shot("editing");
    await page.getByRole("button", { name: "Done" }).tap();
    await page.waitForTimeout(800);
    const committed = await shot("committed");
    out.steps.committed = (await pixels(committed.buffer, RED)).n;
    await undo();
    const undone = await shot("undo-after-place");
    out.steps.afterUndo = (await pixels(undone.buffer, RED)).n;
    await page.getByRole("button", { name: "Redo" }).first().tap().catch(async () => {
      await page.keyboard.press("Control+Shift+z");
    });
    await page.waitForTimeout(600);
    const redone = await shot("redo");
    out.steps.afterRedo = (await pixels(redone.buffer, RED)).n;
    await palette(async (p) => p.getByRole("button", { name: "Select tool" }).tap());
    await tapAt(page, [{ x: at.x + 10, y: at.y }]);
    await page.waitForTimeout(400);
    const edit = await editor.isVisible();
    if (edit) {
      await page.getByRole("button", { name: "Done" }).tap();
      await page.waitForTimeout(500);
    }
    const selected = await shot("selected");
    const blue = await pixels(selected.buffer, BLUE, 40);
    out.steps.selectionBox = blue;
    const grab = { x: blue.maxX / scale - 5, y: blue.maxY / scale - 5 };
    const target = { x: grab.x - 160, y: grab.y };
    await tapAt(page, line(grab, target));
    await page.waitForTimeout(800);
    const resized = await shot("resized-wrap");
    const redBefore = await pixels(redone.buffer, RED);
    const redAfter = await pixels(resized.buffer, RED);
    out.steps.wrapBefore = [redBefore.maxX - redBefore.minX, redBefore.maxY - redBefore.minY].map((v) => Math.round(v / scale));
    out.steps.wrapAfter = [redAfter.maxX - redAfter.minX, redAfter.maxY - redAfter.minY].map((v) => Math.round(v / scale));
    await page.reload({ waitUntil: "load" });
    await page.locator("canvas.surface").waitFor({ state: "visible", timeout: 15000 });
    await page.waitForTimeout(1500);
    const reloaded = await shot("reloaded");
    const redReload = await pixels(reloaded.buffer, RED);
    out.steps.reloaded = [redReload.maxX - redReload.minX, redReload.maxY - redReload.minY].map((v) => Math.round(v / scale));
    await palette(async (p) => {
      await p.getByRole("button", { name: "Colour 4", exact: true }).tap();
      await p.getByRole("button", { name: "Sticky note" }).tap();
    });
    await tapAt(page, [{ x: at.x + 100, y: Math.round(vp.height * 0.65) }]);
    await editor.waitFor({ state: "visible", timeout: 5000 });
    await page.keyboard.type("note");
    await page.getByRole("button", { name: "Done" }).tap();
    await page.waitForTimeout(800);
    const green = [0x30, 0xa4, 0x6c];
    out.steps.stickyPlaced = (await pixels((await shot("sticky-placed")).buffer, green, 12)).n;
    await undo();
    out.steps.stickyUndo1 = (await pixels((await shot("sticky-undo-1")).buffer, green, 12)).n;
    await undo();
    out.steps.stickyUndo2 = (await pixels((await shot("sticky-undo-2")).buffer, green, 12)).n;
  } catch (error) {
    out.error = String(error?.message ?? error).split("\n")[0];
    await shot("failure").catch(() => {});
  } finally {
    out.errors = errors;
    await context.close();
  }
  return out;
};

const browser = await chromium.launch({ headless: true });
try {
  for (const device of ["Galaxy Tab S9", "Pixel 7"]) report.push(await run(browser, device));
} finally {
  await browser.close();
}
console.log(JSON.stringify(report, null, 1));
